     1	import { STORAGE_KEYS } from "@/lib/constants";
     2	import { listConfigBackups, WEB_SLOT_ID } from "@/services/backend-api";
     3	import type { BackupMeta } from "@/services/backend-api";
     4	import { useBackendStore } from "@/store/backend-store";
     5	import { uploadConfigBackup } from "@/services/backend-backup";
     6	import { deleteKey, getString, setString } from "@/store/storage";
     7	
     8	/**
     9	 * Keeps the backend store's view of the "web" slot current (Refs #385).
    10	 *
    11	 * Rules, in order of trust:
    12	 * - A successful list is authoritative: the web slot's revision, or null when
    13	 *   there is none.
    14	 * - A backend that answers 404 or 400 does not have the feature; treat as none.
    15	 * - A network error preserves the last known value.
    16	 * - The applied revision comes from the envelope the phone actually restored
    17	 *   (never from a list or the phone clock) and is cleared on unpair.
    18	 */
    19	
    20	const THROTTLE_MS = 5 * 60 * 1000;
    21	let lastCheckedAt = 0;
    22	let inflight: Promise<void> | null = null;
    23	
    24	export function noteBackupList(backups: BackupMeta[]): void {
    25	  const state = useBackendStore.getState();
    26	  const web = backups.find((b) => b.deviceId === WEB_SLOT_ID);
    27	  state.setWebSlot({ webSlotRevision: web ? web.revision : null });
    28	  // Authoritative list with no slot of our own while backup is on: the slot
    29	  // was deleted or the backend reset. The unchanged-hash skip would otherwise
    30	  // keep us unbacked forever, so force one upload.
    31	  if (state.backupEnabled && !backups.some((b) => b.mine)) {
    32	    deleteKey(STORAGE_KEYS.backendBackupLastHash);
    33	    void uploadConfigBackup({ force: true }).catch((err) => {
    34	      console.warn("[backend-backup] re-upload after missing slot failed", err);
    35	    });
    36	  }
    37	}
    38	
    39	function isUnsupported(err: unknown): boolean {
    40	  const status = (err as { status?: number } | null)?.status;
    41	  return status === 404 || status === 400;
    42	}
    43	
    44	export function checkWebSlot(opts: { force?: boolean } = {}): Promise<void> {
    45	  const state = useBackendStore.getState();
    46	  if (!state.hydrated || !state.url || !state.sharedSecret) return Promise.resolve();
    47	  const now = Date.now();
    48	  if (!opts.force && now - lastCheckedAt < THROTTLE_MS) return Promise.resolve();
    49	  if (inflight) return inflight;
    50	  lastCheckedAt = now;
    51	  inflight = listConfigBackups()
    52	    .then(({ backups }) => noteBackupList(backups))
    53	    .catch((err: unknown) => {
    54	      if (isUnsupported(err)) useBackendStore.getState().setWebSlot({ webSlotRevision: null });
    55	      // Anything else (offline, timeout): keep what we knew.
    56	    })
    57	    .finally(() => {
    58	      inflight = null;
    59	    });
    60	  return inflight;
    61	}
    62	
    63	/** For tests and unpair: forget the throttle window. */
    64	export function resetWebSlotWatch(): void {
    65	  lastCheckedAt = 0;
    66	}
    67	
    68	export function markWebSlotApplied(revision: number): void {
    69	  setString(STORAGE_KEYS.backendWebSlotAppliedRevision, String(revision));
    70	  useBackendStore.getState().setWebSlot({ webSlotAppliedRevision: revision });
    71	}
    72	
    73	export function clearWebSlotApplied(): void {
    74	  deleteKey(STORAGE_KEYS.backendWebSlotAppliedRevision);
    75	  useBackendStore.getState().setWebSlot({ webSlotAppliedRevision: null });
    76	}
    77	
    78	/** Restore the persisted applied revision after both stores hydrated. */
    79	export function loadWebSlotStatus(): void {
    80	  const raw = getString(STORAGE_KEYS.backendWebSlotAppliedRevision);
    81	  const n = raw ? Number(raw) : NaN;
    82	  useBackendStore.getState().setWebSlot({ webSlotAppliedRevision: Number.isFinite(n) ? n : null });
    83	}
